                    }
                },
                "registered_address": {
                    "$ref": "#/definitions/address"
                },
                "headquarters_address": {
                    "$ref": "#/definitions/address"
                },
                "mailing_address": {
                    "$ref": "#/definitions/address"
                },
                "addresses": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/address-with-type"
                    }
                },
                "industry_codes": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/industry-code"
                    }
                },
                "previous_names": {
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/previous-name"
